package timelock_guardian

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
)

// TargetConfig binds a named target to the only address allowed to
// schedule actions against it, an enforced minimum delay, and an
// optional guardian who can veto pending actions. Without this binding
// a timelock attests nothing: anyone could schedule their own
// short-delay action against any name and "execute" it.
type TargetConfig struct {
	Name     string
	Owner    address
	Guardian address // empty = no guardian
	MinDelay int64   // seconds; every action for this target waits at least this
	// PendingOwner is the offered-but-not-accepted new owner (fix Y5:
	// ownership moves in two steps, so a stranger can never have a
	// target — and its quota slot and pending obligations — dumped on
	// them without consenting).
	PendingOwner address
}

// Action represents a scheduled operation that can only execute after
// its delay has elapsed, and only within its grace window.
//
// State model (re-audit 2026-09-02): only PENDING and EXECUTED actions
// are stored. Executed records are permanent attestations consumers
// check via IsExecuted. Cancelled, vetoed, and expired actions are
// REAPED from state — their history lives in emitted events — so the
// live-action cap bounds live exposure and can never be consumed
// permanently by schedule/cancel cycling.
type Action struct {
	ID           string
	Target       string
	Creator      address
	Data         string // encoded call data or description of the action
	ScheduledAt  time.Time
	ExecuteAfter time.Time
	ExpiresAt    time.Time // ExecuteAfter + GracePeriod; not executable after
	Executed     bool
}

const (
	// MinDelayFloor is the smallest minimum delay a target may register.
	// A timelock with a 1-second delay protects nothing.
	MinDelayFloor = int64(60)

	// MaxDelay bounds both registered minimum delays and per-action
	// delays. Also the overflow guard: MaxDelay seconds in nanoseconds
	// is far below int64 range, so ExecuteAfter arithmetic cannot wrap
	// into the past.
	MaxDelay = int64(10 * 365 * 24 * 3600) // 10 years

	// GracePeriod is how long an action stays executable once ready.
	// After it, the action expires: something scheduled and forgotten
	// cannot be sprung on a target years later.
	GracePeriod = int64(30 * 24 * 3600) // 30 days

	// Quotas are PER-OWNER only (re-audit round 3): any global cap is a
	// shared resource a few sybil accounts can exhaust forever (10y
	// delays defeat expiry sweeping), bricking every other tenant. With
	// per-owner quotas an attacker only ever consumes their own budget;
	// state growth is priced in gas and funded accounts.
	MaxTargetsPerOwner  = 10
	MaxPendingPerTarget = 20
	MaxTargetNameLen    = 64
	MaxDataLen          = 2000
	MaxRenderActions    = 100
	// RenderIndexCap bounds the render-ordering index (fix Y4): the
	// index self-trims to this size, so reaping an entry from it is a
	// bounded scan no matter how many actions the realm has ever seen.
	// Records older than the window stay in state (GetAction/IsExecuted
	// are map reads and permanent); they only leave the front page.
	RenderIndexCap = 2 * MaxRenderActions
)

var (
	targets      map[string]*TargetConfig
	targetNames  []string // insertion-ordered for deterministic iteration
	ownerTargets map[address]int
	actions      map[string]*Action
	actionIDs    []string // insertion-ordered render window, self-trimmed to RenderIndexCap
	// pending holds each target's LIVE pending action IDs in insertion
	// order (fix Y4): every list is bounded by MaxPendingPerTarget, so
	// scans, sweeps, and removals are bounded per call regardless of how
	// much state OTHER tenants have grown — queue position in a global
	// list is no longer a shared resource.
	pending map[string][]string
	// pendingTargets lists the targets holding >= 1 live pending action,
	// maintained with O(1) swap-remove via ptIndex (round-2 fix Y-1): no
	// write path ever scans a list another tenant can grow, and
	// GetPending/Render iterate only targets that actually have work.
	pendingTargets []string
	ptIndex        map[string]int
	nextID         int
)

func init() {
	targets = make(map[string]*TargetConfig)
	targetNames = []string{}
	ownerTargets = make(map[address]int)
	actions = make(map[string]*Action)
	actionIDs = []string{}
	pending = make(map[string][]string)
	pendingTargets = []string{}
	ptIndex = make(map[string]int)
	nextID = 1
}

func now() time.Time {
	return time.Now()
}

// ---------- helpers ----------

// rejectStraySend aborts when coins are attached to a call (fix Y6):
// this realm handles no funds and holds no banker, so an attached send
// would strand on the realm address forever. Aborting reverts the
// transfer back to the sender. Fails open for realm-routed calls, whose
// attached send lands on the intermediary realm, never here.
func rejectStraySend(cur realm) {
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("this realm does not accept coins")
	}
}

func mustGetTarget(name string) *TargetConfig {
	t, ok := targets[name]
	if !ok {
		panic("target not found: " + name)
	}
	return t
}

func mustGet(id string) *Action {
	a, ok := actions[id]
	if !ok {
		panic("action not found: " + id)
	}
	return a
}

func isValidName(name string) bool {
	if name == "" || len(name) > MaxTargetNameLen {
		return false
	}
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	return true
}

func expired(a *Action) bool {
	return !a.Executed && now().After(a.ExpiresAt)
}

func removeID(list []string, id string) []string {
	for i, x := range list {
		if x == id {
			return append(list[:i], list[i+1:]...)
		}
	}
	return list
}

func addPendingTarget(target string) {
	if _, ok := ptIndex[target]; ok {
		return
	}
	ptIndex[target] = len(pendingTargets)
	pendingTargets = append(pendingTargets, target)
}

// removePendingTarget drops a target from the with-pendings list in
// O(1) by swapping the last entry into its slot. Order afterwards is
// deterministic (a pure function of the operation history), which is
// all iteration needs.
func removePendingTarget(target string) {
	i, ok := ptIndex[target]
	if !ok {
		return
	}
	last := len(pendingTargets) - 1
	moved := pendingTargets[last]
	pendingTargets[i] = moved
	ptIndex[moved] = i
	pendingTargets = pendingTargets[:last]
	delete(ptIndex, target)
}

// dropPending removes id from its target's pending list. Bounded: the
// list never exceeds MaxPendingPerTarget.
func dropPending(target, id string) {
	l := removeID(pending[target], id)
	if len(l) == 0 {
		delete(pending, target)
		removePendingTarget(target)
	} else {
		pending[target] = l
	}
}

// reap removes a non-executed action from state entirely; its history
// is the emitted event. Executed records are permanent attestations:
// reap refuses them outright (round-2 hardening), so no future caller
// can erase one by mistake.
func reap(id string) {
	a := actions[id]
	if a != nil && a.Executed {
		return
	}
	if a != nil {
		dropPending(a.Target, id)
	}
	delete(actions, id)
	actionIDs = removeID(actionIDs, id)
}

// sweepExpired reaps the expired pending actions of ONE target (fix
// Y4/Y2: the old global budget-windowed sweep let long-delay entries at
// the front of a shared queue starve everything behind them). A
// target's list is bounded by MaxPendingPerTarget, so the sweep is a
// bounded scan. Expiry history is the emitted event.
func sweepExpired(target string) {
	var live []string
	for _, id := range pending[target] {
		a := actions[id]
		if a == nil {
			continue
		}
		if expired(a) {
			chain.Emit("timelock_expired", "id", id, "target", a.Target)
			delete(actions, id)
			actionIDs = removeID(actionIDs, id)
			continue
		}
		live = append(live, id)
	}
	if len(live) == 0 {
		delete(pending, target)
		removePendingTarget(target)
	} else {
		pending[target] = live
	}
}

// pendingCount is the length of the target's live list. The counter it
// replaces (fix Y4) could desync from the lists it mirrored; a length
// cannot. It may briefly include not-yet-swept expired actions; those
// are reaped by the next Schedule's sweep or by anyone's Expire, and in
// the worst case an owner briefly under-uses their own quota — never
// another tenant's.
func pendingCount(target string) int {
	return len(pending[target])
}

// sanitize makes attacker-controlled text safe to embed in markdown and
// single-line summaries: backticks, pipes, newlines, link syntax, and
// raw HTML brackets (fix Y3: gnoweb has no HTML sanitization layer, so
// a literal <script> tag must never reach the page) are replaced so a
// Data string cannot break out of its cell, inject rows or markup, or
// render a live link.
func sanitize(s string) string {
	r := strings.NewReplacer(
		"`", "'", "|", "/", "\n", " ", "\r", " ",
		"[", "(", "]", ")", "*", "·", "_", "-",
		"<", "(", ">", ")",
	)
	return r.Replace(s)
}

// truncate shortens s to at most n runes without splitting a multibyte
// character. n is clamped to a minimum of 4 (re-audit: n<=2 sliced out
// of bounds).
func truncate(s string, n int) string {
	if n < 4 {
		n = 4
	}
	runes := []rune(s)
	if len(runes) <= n {
		return s
	}
	return string(runes[:n-3]) + "..."
}

// ---------- target registration ----------

// RegisterTarget creates a named target. The caller becomes its owner —
// the only address that may schedule actions against it. minDelay is
// the enforced floor for every action's delay. guardian may be empty
// (no guardian) or an address empowered to veto pending actions.
func RegisterTarget(cur realm, name string, minDelay int64, guardian address) {
	rejectStraySend(cur)
	owner := cur.Previous().Address()
	if !isValidName(name) {
		panic("target name must be 1-" + strconv.Itoa(MaxTargetNameLen) +
			" chars, lowercase alphanumeric with underscores only")
	}
	if _, exists := targets[name]; exists {
		panic("target already registered: " + name)
	}
	if ownerTargets[owner] >= MaxTargetsPerOwner {
		panic("per-owner target limit reached")
	}
	if minDelay < MinDelayFloor {
		panic("minimum delay must be at least " + strconv.FormatInt(MinDelayFloor, 10) + " seconds")
	}
	if minDelay > MaxDelay {
		panic("minimum delay exceeds the maximum of " + strconv.FormatInt(MaxDelay, 10) + " seconds")
	}
	if guardian != "" && !guardian.IsValid() {
		panic("invalid guardian address: " + string(guardian))
	}

	targets[name] = &TargetConfig{
		Name:     name,
		Owner:    owner,
		Guardian: guardian,
		MinDelay: minDelay,
	}
	targetNames = append(targetNames, name)
	ownerTargets[owner]++
	chain.Emit("timelock_target_registered", "target", name,
		"owner", string(owner), "guardian", string(guardian),
		"min_delay", strconv.FormatInt(minDelay, 10))
}

// SetGuardian changes (or clears, with "") the target's guardian.
// Owner only, and REFUSED while the target has pending actions: the
// guardian's veto power exists precisely to check the owner during a
// delay window, so the owner must not be able to strip it mid-window.
//
// KNOWN LIMIT (documented, round-3 audit): the owner can cancel all
// pending actions, change the guardian, and reschedule — the price is
// a full fresh MinDelay on every rescheduled action, and every step
// emits an event (cancellations + the guardian change below), so
// observers always get MinDelay of warning under the new guardian
// regime. Guardians protect open windows, not the owner's future.
func SetGuardian(cur realm, targetName string, guardian address) {
	rejectStraySend(cur)
	t := mustGetTarget(targetName)
	if cur.Previous().Address() != t.Owner {
		panic("only the target owner can set the guardian")
	}
	// expired-but-unswept actions protect nothing; sweep them so they
	// cannot block a guardian rotation (round-2 hardening)
	sweepExpired(targetName)
	if pendingCount(targetName) > 0 {
		panic("cannot change the guardian while actions are pending")
	}
	if guardian != "" && !guardian.IsValid() {
		panic("invalid guardian address: " + string(guardian))
	}
	t.Guardian = guardian
	chain.Emit("timelock_guardian_changed", "target", targetName,
		"guardian", string(guardian))
}

// TransferTargetOwnership OFFERS a target to a new owner; the nominee
// must AcceptTargetOwnership to complete it (fix Y5: a one-step
// transfer let anyone fill a stranger's per-owner quota and dump
// pending obligations — with an attacker-chosen guardian — on an
// address that never asked). Owner only. Pass "" to clear a pending
// offer. Nothing changes hands until the nominee accepts.
func TransferTargetOwnership(cur realm, targetName string, newOwner address) {
	rejectStraySend(cur)
	t := mustGetTarget(targetName)
	if cur.Previous().Address() != t.Owner {
		panic("only the target owner can transfer ownership")
	}
	if newOwner == "" {
		t.PendingOwner = ""
		chain.Emit("timelock_ownership_offer_cleared", "target", targetName)
		return
	}
	if !newOwner.IsValid() {
		panic("invalid new owner address: " + string(newOwner))
	}
	if newOwner == t.Owner {
		panic("new owner is already the owner")
	}
	t.PendingOwner = newOwner
	chain.Emit("timelock_ownership_offered", "target", targetName,
		"pending_owner", string(newOwner))
}

// AcceptTargetOwnership completes a pending ownership offer; only the
// nominee can accept. The nominee's quota is checked HERE — consent
// time — so an offer can never overfill an account that did not agree
// to carry it.
func AcceptTargetOwnership(cur realm, targetName string) {
	rejectStraySend(cur)
	t := mustGetTarget(targetName)
	a := cur.Previous().Address()
	if t.PendingOwner == "" || a != t.PendingOwner {
		panic("caller is not the pending owner")
	}
	if ownerTargets[a] >= MaxTargetsPerOwner {
		panic("accepting would exceed the per-owner target limit")
	}
	ownerTargets[t.Owner]--
	if ownerTargets[t.Owner] <= 0 {
		delete(ownerTargets, t.Owner)
	}
	ownerTargets[a]++
	t.Owner = a
	t.PendingOwner = ""
	chain.Emit("timelock_ownership_transferred", "target", targetName,
		"new_owner", string(a))
}

// ---------- write operations ----------

// Schedule creates a new timelocked action against a registered target.
// Only the target's owner may schedule. The delay must be at least the
// target's registered minimum and at most MaxDelay. Returns the action ID.
func Schedule(cur realm, targetName, data string, delay int64) string {
	rejectStraySend(cur)
	t := mustGetTarget(targetName)
	caller := cur.Previous().Address()
	if caller != t.Owner {
		panic("only the target owner can schedule actions for " + targetName)
	}
	if data == "" {
		panic("data must not be empty")
	}
	if len(data) > MaxDataLen {
		panic("data exceeds " + strconv.Itoa(MaxDataLen) + " bytes")
	}
	if delay < t.MinDelay {
		panic("delay below the target's minimum of " + strconv.FormatInt(t.MinDelay, 10) + " seconds")
	}
	if delay > MaxDelay {
		panic("delay exceeds the maximum of " + strconv.FormatInt(MaxDelay, 10) + " seconds")
	}

	sweepExpired(targetName)
	if pendingCount(targetName) >= MaxPendingPerTarget {
		panic("too many pending actions for target " + targetName)
	}

	id := "action_" + strconv.Itoa(nextID)
	nextID++

	ts := now()
	execAfter := ts.Add(time.Duration(delay) * time.Second)
	actions[id] = &Action{
		ID:           id,
		Target:       targetName,
		Creator:      caller,
		Data:         data,
		ScheduledAt:  ts,
		ExecuteAfter: execAfter,
		ExpiresAt:    execAfter.Add(time.Duration(GracePeriod) * time.Second),
	}
	actionIDs = append(actionIDs, id)
	// self-trim (fix Y4): the render index stays bounded, so reaping an
	// entry from it can never become an unbounded scan. Trimmed entries
	// remain in the actions map; only front-page ordering forgets them.
	if len(actionIDs) > RenderIndexCap {
		actionIDs = append([]string{}, actionIDs[len(actionIDs)-MaxRenderActions:]...)
	}
	pending[targetName] = append(pending[targetName], id)
	addPendingTarget(targetName)
	// full-attribute event (round-3 audit): reaped records must be
	// reconstructible from events alone
	chain.Emit("timelock_scheduled", "id", id, "target", targetName,
		"creator", string(caller), "data", data,
		"delay", strconv.FormatInt(delay, 10),
		"execute_after", execAfter.Format(time.RFC3339),
		"expires_at", execAfter.Add(time.Duration(GracePeriod)*time.Second).Format(time.RFC3339))
	return id
}

// Execute marks an action as executed. Anyone can call this — the
// timelock is the protection, not the executor's identity. The action
// must exist, be pending, its delay elapsed, and its grace window not
// yet expired.
func Execute(cur realm, actionID string) string {
	rejectStraySend(cur)
	a := mustGet(actionID)
	if a.Executed {
		panic("action already executed")
	}
	if now().Before(a.ExecuteAfter) {
		remaining := a.ExecuteAfter.Sub(now())
		panic("too early: " + strconv.FormatInt(int64(remaining/time.Second), 10) + "s remaining")
	}
	if now().After(a.ExpiresAt) {
		panic("action expired: the grace window of " +
			strconv.FormatInt(GracePeriod, 10) + "s after readiness has passed")
	}

	a.Executed = true
	dropPending(a.Target, actionID)
	chain.Emit("timelock_executed", "id", actionID, "target", a.Target)
	return "executed: " + actionID
}

// Cancel removes a pending action. Only the target's CURRENT owner can
// cancel (re-audit: the scheduling creator's rights must not survive an
// ownership transfer). The record is reaped; history is the event.
func Cancel(cur realm, actionID string) string {
	rejectStraySend(cur)
	a := mustGet(actionID)
	t := mustGetTarget(a.Target)
	if cur.Previous().Address() != t.Owner {
		panic("only the target owner can cancel")
	}
	if a.Executed {
		panic("cannot cancel an already-executed action")
	}
	if expired(a) {
		panic("action expired: nothing to cancel (use Expire)")
	}

	chain.Emit("timelock_cancelled", "id", actionID, "target", a.Target)
	reap(actionID)
	return "cancelled: " + actionID
}

// Veto cancels a pending action as the target's guardian. This is the
// guardian's whole power: it can stop a scheduled action during the
// delay window, never create or execute one. The record is reaped;
// history is the event.
func Veto(cur realm, actionID string) string {
	rejectStraySend(cur)
	a := mustGet(actionID)
	t := mustGetTarget(a.Target)
	if t.Guardian == "" {
		panic("target has no guardian: " + a.Target)
	}
	if cur.Previous().Address() != t.Guardian {
		panic("only the target guardian can veto")
	}
	if a.Executed {
		panic("cannot veto an already-executed action")
	}
	if expired(a) {
		panic("action expired: nothing to veto (use Expire)")
	}

	chain.Emit("timelock_vetoed", "id", actionID, "target", a.Target)
	reap(actionID)
	return "vetoed: " + actionID
}

// Expire reaps a provably expired action. Permissionless (fix Y2): an
// expired action decides nothing — reaping it only writes down what the
// clock already decided — so anyone may free the quota slot it holds.
// This is the recovery valve that makes a wedged target impossible:
// before it, a phantom expired entry consumed quota and blocked
// SetGuardian until a global sweep happened to reach it; now its own
// target's owner — or anyone else — reaps it directly.
func Expire(cur realm, actionID string) string {
	rejectStraySend(cur)
	a := mustGet(actionID)
	if a.Executed {
		panic("action already executed")
	}
	if !expired(a) {
		panic("action is not expired")
	}
	chain.Emit("timelock_expired", "id", actionID, "target", a.Target)
	reap(actionID)
	return "expired: " + actionID
}

// ---------- read-only queries ----------

// GetTarget returns a formatted summary of a registered target.
func GetTarget(targetName string) string {
	t := mustGetTarget(targetName)
	var b strings.Builder
	b.WriteString("Target: " + t.Name + "\n")
	b.WriteString("Owner: " + string(t.Owner) + "\n")
	guardian := "none"
	if t.Guardian != "" {
		guardian = string(t.Guardian)
	}
	b.WriteString("Guardian: " + guardian + "\n")
	b.WriteString("Min delay: " + strconv.FormatInt(t.MinDelay, 10) + "s\n")
	if t.PendingOwner != "" {
		b.WriteString("Pending owner: " + string(t.PendingOwner) + "\n")
	}
	return b.String()
}

// GetAction returns a formatted summary of a single pending or executed
// action. Cancelled/vetoed/expired actions are reaped — their history
// is in emitted events.
func GetAction(actionID string) string {
	a := mustGet(actionID)
	return formatAction(a)
}

// GetPending returns the IDs of all pending, non-expired actions,
// grouped by target, insertion-ordered within a target. Only targets
// that actually hold live pendings are visited (round-2 fix Y-1), so
// the scan cannot be inflated by registrations alone.
func GetPending() string {
	var results []string
	for _, name := range pendingTargets {
		for _, id := range pending[name] {
			a := actions[id]
			if a == nil || a.Executed || expired(a) {
				continue
			}
			results = append(results, a.ID)
		}
	}
	if len(results) == 0 {
		return "none"
	}
	return strings.Join(results, ", ")
}

// IsReady returns true if the action exists, is pending, its delay has
// elapsed, and it has not expired.
func IsReady(actionID string) bool {
	a, ok := actions[actionID]
	if !ok || a.Executed || expired(a) {
		return false
	}
	return !now().Before(a.ExecuteAfter)
}

// IsExecuted returns true if the action exists and was executed. This is
// the consumer-side check: combined with target registration it attests
// that the target's registered owner scheduled the action, it waited at
// least the registered minimum delay, no guardian vetoed it, and it was
// executed within its grace window. Executed records are permanent.
func IsExecuted(actionID string) bool {
	a, ok := actions[actionID]
	return ok && a.Executed
}

// ---------- render ----------

// Render returns a markdown overview. Never panics. Cancelled, vetoed,
// and expired actions are reaped from state; their history is in
// events. The page shows the most recent actions only (the ordering
// index is bounded — fix Y4); older executed records stay queryable
// via GetAction/IsExecuted forever.
func Render(path string) string {
	if actions == nil || len(actions) == 0 {
		return "# Timelock Guardian\n\nNo actions scheduled.\n"
	}

	// The Pending section reads the live per-target lists, so flooding
	// the realm with executed churn can never push a still-live pending
	// action off the page during its delay window (round-2 fix Y-2).
	var pendingList []*Action
	truncated := false
	for _, name := range pendingTargets {
		for _, id := range pending[name] {
			a := actions[id]
			if a == nil || a.Executed || expired(a) {
				continue
			}
			if len(pendingList) >= MaxRenderActions {
				truncated = true
				break
			}
			pendingList = append(pendingList, a)
		}
		if truncated {
			break
		}
	}

	// The Executed section reads the bounded render index: recent
	// attestations only; older ones stay queryable via GetAction.
	var executedList []*Action
	show := actionIDs
	if len(show) > MaxRenderActions {
		show = show[len(show)-MaxRenderActions:]
		truncated = true
	}
	for _, id := range show {
		a := actions[id]
		if a == nil || !a.Executed {
			continue
		}
		executedList = append(executedList, a)
	}

	var b strings.Builder
	b.WriteString("# Timelock Guardian\n\n")
	if truncated {
		b.WriteString("_Showing at most " + strconv.Itoa(MaxRenderActions) + " actions per section._\n\n")
	}

	section := func(title string, list []*Action) {
		if len(list) == 0 {
			return
		}
		b.WriteString("## " + title + " (" + strconv.Itoa(len(list)) + ")\n\n")
		for _, a := range list {
			b.WriteString(renderActionRow(a))
		}
		b.WriteString("\n")
	}
	section("Pending", pendingList)
	section("Executed", executedList)

	return b.String()
}

// ---------- formatting helpers ----------

func formatAction(a *Action) string {
	var b strings.Builder
	b.WriteString("ID: " + a.ID + "\n")
	b.WriteString("Target: " + sanitize(a.Target) + "\n")
	b.WriteString("Creator: " + string(a.Creator) + "\n")
	b.WriteString("Data: " + sanitize(a.Data) + "\n")
	b.WriteString("Scheduled: " + a.ScheduledAt.Format(time.RFC3339) + "\n")
	b.WriteString("Execute after: " + a.ExecuteAfter.Format(time.RFC3339) + "\n")
	b.WriteString("Expires: " + a.ExpiresAt.Format(time.RFC3339) + "\n")

	switch {
	case a.Executed:
		b.WriteString("Status: executed\n")
	case expired(a):
		b.WriteString("Status: expired\n")
	case now().Before(a.ExecuteAfter):
		remaining := a.ExecuteAfter.Sub(now())
		b.WriteString("Status: locked (" + strconv.FormatInt(int64(remaining/time.Second), 10) + "s remaining)\n")
	default:
		b.WriteString("Status: ready\n")
	}
	return b.String()
}

func renderActionRow(a *Action) string {
	data := truncate(sanitize(a.Data), 40)

	status := "pending"
	switch {
	case a.Executed:
		status = "executed"
	case expired(a):
		status = "expired"
	case !now().Before(a.ExecuteAfter):
		status = "**ready**"
	}

	return "- **" + a.ID + "** | target: `" + sanitize(a.Target) + "` | " + data + " | " + status + "\n"
}

package upgrade_registry

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"
)

// ContractEntry represents a registered contract and its upgrade status.
//
// An entry's Address is ALWAYS the address that called Register — a
// contract can only register itself. That call is the proof of control:
// nobody can claim an address they don't command, so a Deprecate
// redirect on an entry always originates from whoever genuinely
// controlled the contract. Entries are permanent by design: migration
// history is what consumers rely on, so it must not be erasable (and a
// delete would reopen re-registration squatting).
//
// Ownership is two-step (re-audit 2026-09-02): Register/Transfer only
// NOMINATE an owner; the nominee must AcceptOwnership. Until then the
// entry is owned by the contract itself, so nobody's address can be
// attached as "owner" without their consent.
type ContractEntry struct {
	Address      address
	Owner        address // current manager (accepted)
	PendingOwner address // nominated, not yet accepted; empty if none
	Name         string
	Deprecated   bool
	Successor    address // address of the upgraded contract, empty if current
}

const (
	MaxNameLen  = 64
	MaxChainLen = 50 // GetMigrationChain traversal/output bound (marked when hit)

	// Render bounds (re-audit): rendering is paginated and the per-row
	// "latest" annotation walks a bounded number of hops, so an
	// attacker-built long chain cannot blow up the realm page.
	MaxRenderEntries = 100
	RenderLatestHops = 10
)

// NOTE (re-audit): there is deliberately NO global entry cap. Entries
// are one-per-address by construction (self-registration), so spam
// costs funded accounts and gas; a hard cap combined with the
// registered-successor rule would let an attacker saturate the
// registry and permanently disable deprecation for every legitimate
// entry.

var (
	entries        map[address]*ContractEntry
	entryAddrs     []address // insertion-ordered for deterministic Render
	ownerContracts map[address][]address
)

func init() {
	entries = make(map[address]*ContractEntry)
	entryAddrs = []address{}
	ownerContracts = make(map[address][]address)
}

// rejectStraySend aborts when coins are attached to a call (audit Y2):
// this realm handles no funds and holds no banker, so an attached send
// would strand on the realm address forever. Aborting reverts the
// transfer back to the sender. Fails open for realm-routed calls, whose
// attached send lands on the intermediary realm, never here.
func rejectStraySend(cur realm) {
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("this realm does not accept coins")
	}
}

// isValidName restricts names to lowercase alphanumeric with
// underscores. Names appear in rendered markdown and query output, so
// no delimiter or markdown character may enter one.
func isValidName(name string) bool {
	if name == "" || len(name) > MaxNameLen {
		return false
	}
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	return true
}

func ownerIndexRemove(owner, contractAddr address) {
	old := ownerContracts[owner]
	for i, addr := range old {
		if addr == contractAddr {
			ownerContracts[owner] = append(old[:i], old[i+1:]...)
			break
		}
	}
	if len(ownerContracts[owner]) == 0 {
		delete(ownerContracts, owner)
	}
}

// ---------- write operations ----------

// Register adds the CALLING contract to the registry — the entry's
// address is the caller's own address, which is the proof of control.
// owner NOMINATES a manager (team EOA or governance realm); it holds no
// power until it calls AcceptOwnership (nobody can be made an owner
// without consent — re-audit). Pass "" to manage from the contract
// itself — but note (audit Y4): entries are permanent, so an entry
// managed by a contract that has no code path for calling this
// registry again is FROZEN as active forever: never deprecatable,
// never transferable. Realms registering from init() should nominate
// an EOA or governance manager instead.
func Register(cur realm, name string, owner address) string {
	rejectStraySend(cur)
	if !isValidName(name) {
		panic("name must be 1-" + strconv.Itoa(MaxNameLen) +
			" chars, lowercase alphanumeric with underscores only")
	}
	contractAddr := cur.Previous().Address()
	if _, exists := entries[contractAddr]; exists {
		panic("contract already registered: " + string(contractAddr))
	}
	pending := address("")
	if owner != "" && owner != contractAddr {
		if !owner.IsValid() {
			panic("invalid owner address: " + string(owner))
		}
		pending = owner
	}

	entries[contractAddr] = &ContractEntry{
		Address:      contractAddr,
		Owner:        contractAddr,
		PendingOwner: pending,
		Name:         name,
	}
	entryAddrs = append(entryAddrs, contractAddr)
	ownerContracts[contractAddr] = append(ownerContracts[contractAddr], contractAddr)
	return "registered " + name + " at " + string(contractAddr)
}

// AcceptOwnership completes a nominated ownership: only the pending
// owner can accept, and only acceptance moves the entry (and the
// ownerContracts index) to them.
func AcceptOwnership(cur realm, contractAddr address) string {
	rejectStraySend(cur)
	entry := mustGet(contractAddr)
	c := cur.Previous().Address()
	if entry.PendingOwner == "" || c != entry.PendingOwner {
		panic("caller is not the pending owner of " + string(contractAddr))
	}
	ownerIndexRemove(entry.Owner, contractAddr)
	ownerContracts[c] = append(ownerContracts[c], contractAddr)
	entry.Owner = c
	entry.PendingOwner = ""
	return "ownership accepted by " + string(c)
}

// TransferOwnership NOMINATES a new owner for a registry entry; the
// nominee must AcceptOwnership to take control (two-step — re-audit).
// Passing "" clears a pending nomination.
func TransferOwnership(cur realm, contractAddr, newOwner address) string {
	rejectStraySend(cur)
	entry := mustGet(contractAddr)
	if entry.Owner != cur.Previous().Address() {
		panic("only the owner can transfer ownership")
	}
	if newOwner == "" {
		entry.PendingOwner = ""
		return "pending ownership nomination cleared"
	}
	if !newOwner.IsValid() {
		panic("invalid new owner address: " + string(newOwner))
	}
	entry.PendingOwner = newOwner
	return "ownership nominated to " + string(newOwner) + " (pending acceptance)"
}

// Deprecate marks a contract as deprecated and points to its successor.
// Only the entry's owner can deprecate. The successor must itself be a
// REGISTERED entry — registration is self-proving, so a successor can
// never be a dangling pointer or an address squatted by a third party —
// and the successor entry must be OWNED BY THE CALLER (re-audit: without
// consent, an attacker could chain their entry INTO a legitimate
// contract, forging "official predecessor" provenance). Consent is
// checked AT CALL TIME: transferring the successor entry away later
// does not unlink an existing chain — the attestation is that both
// ends shared an owner when the deprecation was recorded.
func Deprecate(cur realm, contractAddr, successorAddr address) string {
	rejectStraySend(cur)
	entry := mustGet(contractAddr)
	if entry.Owner != cur.Previous().Address() {
		panic("only the owner can deprecate this contract")
	}
	if entry.Deprecated {
		panic("contract is already deprecated")
	}
	if successorAddr == contractAddr {
		panic("successor cannot be the contract itself")
	}
	succ, exists := entries[successorAddr]
	if !exists {
		panic("successor is not a registered contract: " + string(successorAddr))
	}
	if succ.Owner != cur.Previous().Address() {
		panic("successor entry is not owned by the caller: " + string(successorAddr))
	}

	// Prevent circular chains: walk from successor and ensure we don't
	// loop back to contractAddr. Successors are immutable once set, so
	// a check over the existing chain is complete.
	visited := make(map[address]bool)
	visited[contractAddr] = true
	walk := successorAddr
	for hops := 0; ; hops++ {
		if hops > MaxChainLen {
			// bounded-walk discipline (round-3 audit): a successor chain
			// this long is pathological; refuse rather than walk unbounded
			panic("successor chain too long to verify; cannot deprecate")
		}
		if visited[walk] {
			panic("deprecating " + string(contractAddr) + " to " +
				string(successorAddr) + " would create a circular migration chain")
		}
		e, exists := entries[walk]
		if !exists || !e.Deprecated || e.Successor == "" {
			break
		}
		visited[walk] = true
		walk = e.Successor
	}

	entry.Deprecated = true
	entry.Successor = successorAddr
	return "deprecated " + entry.Name + ", successor: " + string(successorAddr)
}

// ---------- read-only queries ----------

// GetLatest follows the migration chain from a contract address and
// returns the latest non-deprecated address. Safe against circular refs.
//
// COST WARNING (audit Y3): unlike the write-path walks, this read is
// deliberately UNBOUNDED in hops so it always resolves the true
// endpoint. Chain length is attacker-buildable, so an on-chain
// integrator resolving an UNTRUSTED address inside its own transaction
// must treat the gas cost as O(chain length) — wrap it, bound the
// input set, or resolve off-chain via query.
func GetLatest(contractAddr address) address {
	visited := make(map[address]bool)
	current := contractAddr

	for {
		entry, exists := entries[current]
		if !exists {
			return current
		}
		if !entry.Deprecated || entry.Successor == "" {
			return current
		}
		if visited[current] {
			return current // break on circular
		}
		visited[current] = true
		current = entry.Successor
	}
}

// GetMigrationChain returns the full upgrade path starting from the
// given address, at most MaxChainLen hops. A chain longer than the
// bound is explicitly marked as truncated (re-audit: silent truncation
// presented a mid-chain node as the endpoint).
func GetMigrationChain(contractAddr address) string {
	visited := make(map[address]bool)
	current := contractAddr
	var parts []string

	for {
		if len(parts) >= MaxChainLen {
			parts = append(parts, "... (truncated at "+strconv.Itoa(MaxChainLen)+
				" hops; use GetLatest for the endpoint)")
			break
		}
		entry, exists := entries[current]
		if !exists {
			if len(parts) == 0 {
				return "not found: " + string(contractAddr)
			}
			parts = append(parts, string(current)+" (unregistered)")
			break
		}
		if visited[current] {
			parts = append(parts, string(current)+" (circular)")
			break
		}
		visited[current] = true

		tag := ""
		if entry.Deprecated {
			tag = " [deprecated]"
		}
		parts = append(parts, string(entry.Address)+" ("+entry.Name+")"+tag)

		if !entry.Deprecated || entry.Successor == "" {
			break
		}
		current = entry.Successor
	}

	return strings.Join(parts, " -> ")
}

// GetInfo returns a one-line summary for a contract.
func GetInfo(contractAddr address) string {
	entry := mustGet(contractAddr)
	status := "active"
	if entry.Deprecated {
		status = "deprecated -> " + string(entry.Successor)
	}
	return entry.Name + " | owner: " + string(entry.Owner) + " | " + status
}

// GetOwnerContracts returns all contract addresses whose ACCEPTED owner
// is the given address (nominations don't count until accepted).
func GetOwnerContracts(owner address) string {
	addrs, exists := ownerContracts[owner]
	if !exists || len(addrs) == 0 {
		return "none"
	}
	parts := make([]string, len(addrs))
	for i, a := range addrs {
		parts[i] = string(a)
	}
	return strings.Join(parts, ", ")
}

// ---------- render ----------

// renderLatest walks at most RenderLatestHops hops for the per-row
// annotation; longer chains are marked rather than walked (render gas
// bound — re-audit).
func renderLatest(contractAddr address) (address, bool) {
	current := contractAddr
	for i := 0; i < RenderLatestHops; i++ {
		entry, exists := entries[current]
		if !exists || !entry.Deprecated || entry.Successor == "" {
			return current, true
		}
		current = entry.Successor
	}
	// round-3 audit off-by-one: the node reached ON the budget boundary
	// may itself be terminal — check before declaring the walk incomplete
	entry, exists := entries[current]
	if !exists || !entry.Deprecated || entry.Successor == "" {
		return current, true
	}
	return current, false
}

// Render returns a markdown overview of the most recent entries.
// Never panics.
func Render(path string) string {
	if entries == nil || len(entries) == 0 {
		return "# Upgrade Registry\n\nNo contracts registered.\n"
	}

	var b strings.Builder
	b.WriteString("# Upgrade Registry\n\n")
	b.WriteString("**Registered contracts:** " + strconv.Itoa(len(entries)) + "\n\n")

	show := entryAddrs
	if len(show) > MaxRenderEntries {
		b.WriteString("_Showing the most recent " + strconv.Itoa(MaxRenderEntries) +
			" entries._\n\n")
		show = show[len(show)-MaxRenderEntries:]
	}

	var active []string
	var deprecated []string

	for _, addr := range show {
		entry := entries[addr]
		if entry == nil {
			continue
		}
		line := "- **" + entry.Name + "** (`" + string(addr) + "`) — owner: `" + string(entry.Owner) + "`"
		if entry.Deprecated {
			line += " — **DEPRECATED** -> `" + string(entry.Successor) + "`"
			latest, complete := renderLatest(addr)
			if !complete {
				line += " (long chain; use GetLatest)"
			} else if latest != entry.Successor {
				line += " (latest: `" + string(latest) + "`)"
			}
			deprecated = append(deprecated, line)
		} else {
			active = append(active, line)
		}
	}

	if len(active) > 0 {
		b.WriteString("## Active\n\n")
		for _, l := range active {
			b.WriteString(l + "\n")
		}
		b.WriteString("\n")
	}

	if len(deprecated) > 0 {
		b.WriteString("## Deprecated\n\n")
		for _, l := range deprecated {
			b.WriteString(l + "\n")
		}
		b.WriteString("\n")
	}

	return b.String()
}

// ---------- helpers ----------

func mustGet(addr address) *ContractEntry {
	entry, ok := entries[addr]
	if !ok {
		panic("contract not found: " + string(addr))
	}
	return entry
}

package permission_registry

import (
	"chain/runtime/unsafe"
	"sort"
	"strconv"
	"strings"
	"time"
)

const (
	// MaxResources bounds total registry state. Raised from the upstream
	// 200 as part of the R1 remediation: with a per-admin quota now
	// carrying the anti-monopoly duty, the global cap is a pure state
	// bound rather than the sole defense against namespace exhaustion.
	MaxResources = 1000

	// MaxResourcesPerAdmin bounds how many resources one address may hold
	// at once. R1 (audit 2026-09-21): the upstream design had only a
	// global cap on a permissionless shared registry, so one unprivileged
	// key could occupy every slot for ~200 cheap transactions and
	// permanently deny the registry to every other tenant. DeleteResource
	// is admin-only, so the squat was irreversible.
	MaxResourcesPerAdmin = 20

	MaxPermissionsPerResource = 50
	MaxHoldersPerPermission   = 200
	MaxNameLen                = 64

	// ReservationPeriod is how long a deleted resource name stays
	// reserved. Finite (re-audit 2026-09-02): eternal tombstones let an
	// attacker cycle create/delete to lock the namespace forever.
	ReservationPeriod = int64(90 * 24 * 3600) // 90 days

	// Render bounds (Y3, audit 2026-09-21). Render walks the whole
	// registry and is reachable by any viewer through gnoweb and
	// vm/qrender, so its cost is borne by third parties rather than by
	// whoever grew the state. Uncapped, the declared limits allowed
	// 1000*50*200 rendered holder entries. The full data stays available
	// through ListResources / GetPermissions / Has, which are bounded per
	// call by construction.
	MaxRenderResources   = 20
	MaxRenderPermissions = 8
	MaxRenderHolders     = 10
)

// Reservation holds a deleted resource name for its former admin AND
// its original creator, and expires.
type Reservation struct {
	Admin   address
	Creator address
	Expires time.Time
}

// resources maps a resource name to the admin address that controls it.
var resources map[string]address

// resourceNames tracks the insertion-ordered list of resource names so
// ListResources can iterate without scanning the map.
var resourceNames []string

// permissions maps resource -> permission -> address -> granted.
// Three-level nesting gives O(1) lookup for Has().
var permissions map[string]map[string]map[address]bool

// permList tracks the ordered list of distinct permission names per
// resource, so GetPermissions can iterate without scanning the full map.
var permList map[string][]string

// retired maps a deleted resource name to its time-bounded
// reservation. Consumers authorize against resource names, so a
// freed name must not be claimable by an attacker while integrators
// may still reference it — but the hold expires so tombstones cannot
// lock the namespace forever.
var retired map[string]*Reservation

// resourceCreators records each resource's ORIGINAL creator,
// immutable through admin transfers, so a hostile admin-transferee
// cannot permanently strand a name against the project that made it.
var resourceCreators map[string]address

// adminResources counts the live resources each address administers, so
// MaxResourcesPerAdmin can be enforced in O(1). Entries are removed when
// the count reaches zero so the map tracks live admins only (R1).
var adminResources map[address]int

// pendingAdmins holds nominated-but-not-yet-accepted admins, keyed by
// resource name. Admin handoff is two-step (Y4): nominating is
// reversible, only the nominee's own acceptance is final.
var pendingAdmins map[string]address

func init() {
	resources = make(map[string]address)
	resourceNames = []string{}
	permissions = make(map[string]map[string]map[address]bool)
	permList = make(map[string][]string)
	retired = make(map[string]*Reservation)
	resourceCreators = make(map[string]address)
	adminResources = make(map[address]int)
	pendingAdmins = make(map[string]address)
}

// mustBeAdmin panics if who is not the admin of the resource.
//
// Y1 (audit 2026-09-21): identity is now passed in from the crossing
// entrypoint's own `cur.Previous().Address()` rather than recomputed by
// a non-crossing helper via unsafe.PreviousRealm(). The stack-walking
// form returned the correct address on every path this realm actually
// exposes, but nothing in the type system tied it to the immediate
// caller — a future non-crossing exported helper calling it would have
// silently resolved its importer's caller instead of its importer
// (security.md Class 2). Threading `cur` makes the binding structural.
func mustBeAdmin(who address, resource string) {
	admin, exists := resources[resource]
	if !exists {
		panic("resource not found: " + resource)
	}
	if who != admin {
		panic("permission denied: caller is not admin of " + resource)
	}
}

// rejectStraySend aborts a transaction that attaches coins. This realm
// has no banker, no payable path and no withdrawal function, so coins
// attached to any entrypoint would be permanently stranded at the realm
// address (Y5, security.md § operational).
func rejectStraySend(cur realm) {
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("this realm does not accept coins")
	}
}

// releaseAdminSlot decrements an admin's live-resource count, deleting
// the entry when it reaches zero so adminResources never accumulates
// zero-valued keys.
func releaseAdminSlot(a address) {
	adminResources[a]--
	if adminResources[a] <= 0 {
		delete(adminResources, a)
	}
}

// isValidName restricts resource and permission names to lowercase
// alphanumeric with underscores. Beyond hygiene this is a security
// property: names appear in composite trust decisions and rendered
// output, so no delimiter or markdown character may enter one.
func isValidName(name string) bool {
	if name == "" || len(name) > MaxNameLen {
		return false
	}
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	return true
}

func nameRuleText(kind string) string {
	return kind + " name must be 1-" + strconv.Itoa(MaxNameLen) +
		" chars, lowercase alphanumeric with underscores only"
}

// ---------- write operations ----------

// CreateResource registers a new named resource. The caller becomes its
// admin and is the only address that can grant or revoke permissions on
// it. A deleted resource name stays reserved for its former admin and
// its original creator until the reservation expires.
//
// Each address may administer at most MaxResourcesPerAdmin resources at
// once, and the registry holds at most MaxResources in total.
func CreateResource(cur realm, resourceName string) {
	rejectStraySend(cur)
	who := cur.Previous().Address()

	if !isValidName(resourceName) {
		panic(nameRuleText("resource"))
	}
	if _, exists := resources[resourceName]; exists {
		panic("resource already exists: " + resourceName)
	}

	creator := who
	if res, wasRetired := retired[resourceName]; wasRetired {
		if time.Now().After(res.Expires) {
			// The hold lapsed: drop the tombstone now rather than leaving
			// it for the success path below, so a lapsed reservation is
			// reclaimed even if this call goes on to abort.
			delete(retired, resourceName)
		} else {
			if who != res.Admin && who != res.Creator {
				panic("resource name is reserved for its former admin: " + resourceName)
			}
			// round-3 audit: an in-window re-create must PRESERVE the
			// original creator — otherwise a hostile admin-transferee could
			// delete and instantly re-create, erasing the original project's
			// reclaim right for every future cycle
			if res.Creator != "" {
				creator = res.Creator
			}
		}
	}
	if len(resources) >= MaxResources {
		panic("global resource limit reached")
	}
	if adminResources[who] >= MaxResourcesPerAdmin {
		panic("per-admin resource limit reached")
	}

	resources[resourceName] = who
	adminResources[who]++
	resourceCreators[resourceName] = creator
	resourceNames = append(resourceNames, resourceName)
	permissions[resourceName] = make(map[string]map[address]bool)
	permList[resourceName] = []string{}
	delete(retired, resourceName)
}

// DeleteResource removes a resource and every permission under it. Only
// the resource admin can call this. The name stays reserved for the
// caller and for the original creator: nobody else can re-create it and
// inherit its consumers until the reservation expires.
func DeleteResource(cur realm, resourceName string) {
	rejectStraySend(cur)
	who := cur.Previous().Address()
	mustBeAdmin(who, resourceName)

	retired[resourceName] = &Reservation{
		Admin:   who,
		Creator: resourceCreators[resourceName],
		Expires: time.Now().Add(time.Duration(ReservationPeriod) * time.Second),
	}
	releaseAdminSlot(who)
	delete(resources, resourceName)
	delete(resourceCreators, resourceName)
	delete(permissions, resourceName)
	delete(permList, resourceName)
	// a nomination cannot outlive the resource it was made against
	delete(pendingAdmins, resourceName)
	for i, n := range resourceNames {
		if n == resourceName {
			resourceNames = append(resourceNames[:i], resourceNames[i+1:]...)
			break
		}
	}
}

// Grant gives an address a named permission on a resource. Only the
// resource admin can call this. Panics if the permission is already
// granted to avoid silent no-ops.
func Grant(cur realm, resourceName, permission string, addr address) {
	rejectStraySend(cur)
	mustBeAdmin(cur.Previous().Address(), resourceName)
	if !isValidName(permission) {
		panic(nameRuleText("permission"))
	}
	if addr == "" || !addr.IsValid() {
		panic("invalid address: " + string(addr))
	}

	perms := permissions[resourceName]
	if perms[permission] == nil {
		if len(permList[resourceName]) >= MaxPermissionsPerResource {
			panic("permission limit reached for resource " + resourceName)
		}
		perms[permission] = make(map[address]bool)
		permList[resourceName] = append(permList[resourceName], permission)
	}

	if perms[permission][addr] {
		panic("permission already granted: " + permission + " to " + string(addr))
	}
	if len(perms[permission]) >= MaxHoldersPerPermission {
		panic("holder limit reached for permission " + permission)
	}
	perms[permission][addr] = true
}

// Revoke removes a permission from an address. Only the resource admin
// can call this. Panics if the permission was not granted. A permission
// left with no holders is pruned from the resource's permission list.
func Revoke(cur realm, resourceName, permission string, addr address) {
	rejectStraySend(cur)
	mustBeAdmin(cur.Previous().Address(), resourceName)

	perms := permissions[resourceName]
	if perms[permission] == nil || !perms[permission][addr] {
		panic("permission not granted: " + permission + " to " + string(addr))
	}
	delete(perms[permission], addr)

	if len(perms[permission]) == 0 {
		delete(perms, permission)
		for i, p := range permList[resourceName] {
			if p == permission {
				permList[resourceName] = append(permList[resourceName][:i], permList[resourceName][i+1:]...)
				break
			}
		}
	}
}

// TransferAdmin nominates a new admin for a resource. Only the current
// admin can call this, and the handoff does NOT take effect until the
// nominee calls AcceptAdmin.
//
// Y4 (audit 2026-09-21): the upstream one-step transfer made a
// well-formed-but-unowned destination permanently fatal. address.IsValid
// only checks bech32 form, so a mistyped address passed the check and
// left the resource with an admin nobody controls — it could never again
// be granted on, revoked from, transferred or deleted, and its slot was
// lost from both the global cap and the former admin's quota forever.
// Nomination is reversible; only the nominee's consent is final.
func TransferAdmin(cur realm, resourceName string, newAdmin address) {
	rejectStraySend(cur)
	who := cur.Previous().Address()
	mustBeAdmin(who, resourceName)
	if newAdmin == "" || !newAdmin.IsValid() {
		panic("invalid new admin address: " + string(newAdmin))
	}
	if newAdmin == who {
		panic("new admin is already the admin of " + resourceName)
	}
	pendingAdmins[resourceName] = newAdmin
}

// CancelAdminTransfer withdraws a pending nomination. Only the current
// admin can call this.
func CancelAdminTransfer(cur realm, resourceName string) {
	rejectStraySend(cur)
	mustBeAdmin(cur.Previous().Address(), resourceName)
	if _, ok := pendingAdmins[resourceName]; !ok {
		panic("no pending admin transfer for " + resourceName)
	}
	delete(pendingAdmins, resourceName)
}

// AcceptAdmin completes a pending handoff; only the nominee may call it.
// The nominee's quota is checked HERE — at consent time — so a
// nomination can never push an account past MaxResourcesPerAdmin without
// that account agreeing to carry the resource.
func AcceptAdmin(cur realm, resourceName string) {
	rejectStraySend(cur)
	who := cur.Previous().Address()

	nominee, pending := pendingAdmins[resourceName]
	if !pending {
		panic("no pending admin transfer for " + resourceName)
	}
	if who != nominee {
		panic("caller is not the pending admin of " + resourceName)
	}
	former, exists := resources[resourceName]
	if !exists {
		panic("resource not found: " + resourceName)
	}
	if adminResources[who] >= MaxResourcesPerAdmin {
		panic("accepting would exceed the per-admin resource limit")
	}

	releaseAdminSlot(former)
	adminResources[who]++
	resources[resourceName] = who
	delete(pendingAdmins, resourceName)
}

// ---------- read-only queries ----------

// Has returns true if addr holds the named permission on the resource.
// Returns false (never panics) for unknown resources or permissions.
//
// INTEGRATOR CONTRACT (Y7): Has takes the subject address explicitly and
// performs NO caller authentication — it answers "does this address hold
// this permission", not "may my caller do this". A consuming realm must
// derive addr from its own crossing entrypoint's cur.Previous().Address()
// and pass it in. Deriving it inside a non-crossing helper via
// unsafe.PreviousRealm() resolves the consumer's own caller's caller and
// is a Class-2 designation-forgery bug in the consumer.
func Has(resourceName, permission string, addr address) bool {
	perms, exists := permissions[resourceName]
	if !exists {
		return false
	}
	holders := perms[permission]
	if holders == nil {
		return false
	}
	return holders[addr]
}

// GetPermissions returns all permission names granted to addr on a
// resource, as a comma-separated string. Returns "none" if the address
// has no permissions.
func GetPermissions(resourceName string, addr address) string {
	perms, exists := permissions[resourceName]
	if !exists {
		return "none"
	}

	var result []string
	for _, perm := range permList[resourceName] {
		holders := perms[perm]
		if holders != nil && holders[addr] {
			result = append(result, perm)
		}
	}
	if len(result) == 0 {
		return "none"
	}
	return strings.Join(result, ", ")
}

// ListResources returns all registered resource names as a comma-separated
// string in registration order. Returns "none" if no resources exist.
func ListResources() string {
	if len(resourceNames) == 0 {
		return "none"
	}
	return strings.Join(resourceNames, ", ")
}

// GetAdmin returns the admin address of a resource.
func GetAdmin(resourceName string) string {
	admin, exists := resources[resourceName]
	if !exists {
		return "not found"
	}
	return string(admin)
}

// GetPendingAdmin returns the nominated admin awaiting acceptance for a
// resource, or "none".
func GetPendingAdmin(resourceName string) string {
	a, ok := pendingAdmins[resourceName]
	if !ok {
		return "none"
	}
	return string(a)
}

// ---------- render ----------

// Render returns a markdown overview. Never panics. Output is bounded
// by MaxRenderResources / MaxRenderPermissions / MaxRenderHolders (Y3);
// truncated sections name the query to use for complete data.
func Render(path string) string {
	if resources == nil || len(resourceNames) == 0 {
		return "# Permission Registry\n\nNo resources registered.\n"
	}

	var b strings.Builder
	b.WriteString("# Permission Registry\n\n")
	b.WriteString("Registered resources: " + strconv.Itoa(len(resourceNames)) + "\n\n")

	shown := len(resourceNames)
	if shown > MaxRenderResources {
		shown = MaxRenderResources
	}

	for _, name := range resourceNames[:shown] {
		admin := resources[name]
		b.WriteString("## " + name + "\n\n")
		b.WriteString("**Admin:** `" + string(admin) + "`\n\n")
		if p, ok := pendingAdmins[name]; ok {
			b.WriteString("**Pending admin:** `" + string(p) + "` (awaiting acceptance)\n\n")
		}

		perms, exists := permissions[name]
		if !exists || len(perms) == 0 {
			b.WriteString("_No permissions defined._\n\n")
			continue
		}

		names := permList[name]
		pShown := len(names)
		if pShown > MaxRenderPermissions {
			pShown = MaxRenderPermissions
		}

		b.WriteString("| Permission | Addresses |\n")
		b.WriteString("|------------|-----------|\n")

		for _, perm := range names[:pShown] {
			holders := perms[perm]
			if holders == nil || len(holders) == 0 {
				continue
			}
			var addrs []string
			for addr := range holders {
				if holders[addr] {
					addrs = append(addrs, string(addr))
				}
			}
			// sort the FULL holder set before truncating, so the subset
			// shown is a deterministic function of state rather than of
			// map layout
			sort.Strings(addrs)
			extra := 0
			if len(addrs) > MaxRenderHolders {
				extra = len(addrs) - MaxRenderHolders
				addrs = addrs[:MaxRenderHolders]
			}
			for i, a := range addrs {
				addrs[i] = "`" + a + "`"
			}
			cell := strings.Join(addrs, ", ")
			if extra > 0 {
				cell += ", … +" + strconv.Itoa(extra) + " more"
			}
			b.WriteString("| " + perm + " | " + cell + " |\n")
		}
		if len(names) > pShown {
			b.WriteString("\n_… " + strconv.Itoa(len(names)-pShown) +
				" more permission(s) on this resource. Use GetPermissions or Has for complete data._\n")
		}
		b.WriteString("\n")
	}

	if len(resourceNames) > shown {
		b.WriteString("_… " + strconv.Itoa(len(resourceNames)-shown) +
			" more resource(s) not shown. Use ListResources, GetPermissions or Has for complete data._\n")
	}

	return b.String()
}

package service_registry

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// Service represents a registered on-chain service.
type Service struct {
	Name        string
	Owner       address
	Registrant  address // ORIGINAL registrant; immutable through transfers
	PkgPath     string  // the realm the service lives at — what integrators resolve
	Description string
	ServiceType string // e.g. "token", "dex", "oracle", "dao", "nft", "bridge"
	Metadata    string // freeform key=value pairs or JSON blob
}

// Reservation holds a deregistered name for its former owner AND its
// original registrant, and EXPIRES (re-audit 2026-09-02): an eternal
// reservation let an attacker cycle register/deregister to lock the
// whole namespace forever, and a hostile transferee could strand a
// name against its original registrant permanently.
type Reservation struct {
	Owner      address
	Registrant address
	Expires    time.Time
}

const (
	// MaxServices is a pure state bound, not an anti-squat defense —
	// MaxServicesPerOwner is what makes monopolization expensive
	// (pearl audit R1). Kept at 1000 rather than raised further so the
	// linear scans over `names` (Deregister, ListServices, ListByType)
	// stay bounded at a size one transaction can comfortably pay for.
	MaxServices = 1000

	// MaxServicesPerOwner caps how many names one address may hold at
	// once. Enforced at registration and, for a handoff, at the moment
	// the recipient CONSENTS (see AcceptOwnership).
	MaxServicesPerOwner = 20

	MaxNameLen        = 64
	MaxTypeLen        = 32
	MaxPkgPathLen     = 128
	MaxDescriptionLen = 500
	MaxMetadataLen    = 2000

	pkgPathPrefix = "gno.land/"

	// ReservationPeriod is how long a deregistered name stays reserved.
	// Long enough for integrators to notice the deregistration; finite
	// so tombstones cannot lock the namespace forever.
	ReservationPeriod = int64(90 * 24 * 3600) // 90 days

	// MaxRenderServices bounds the gnoweb table. Render is reachable by
	// any viewer, so its cost lands on third parties rather than on
	// whoever grew the state (pearl audit Y3). Complete data comes from
	// the bounded queries named in the truncation notice.
	MaxRenderServices = 25

	// renderDescLen is the per-row description budget, applied to the
	// RAW text before escaping so an escape sequence is never split.
	renderDescLen = 60
)

var (
	services map[string]*Service
	names    []string // insertion-ordered list for deterministic iteration
	// retired maps a deregistered name to its time-bounded reservation.
	retired map[string]*Reservation
	// ownerServices is the O(1) index backing MaxServicesPerOwner. It is
	// kept zero-free: an owner that drops to zero is deleted outright so
	// the map cannot accumulate dead keys.
	ownerServices map[address]int
	// pendingOwners holds nominated-but-not-yet-accepted owners
	// (pearl audit Y4). A name appears here only while a handoff is open.
	pendingOwners map[string]address
)

func init() {
	services = make(map[string]*Service)
	names = []string{}
	retired = make(map[string]*Reservation)
	ownerServices = make(map[address]int)
	pendingOwners = make(map[string]address)
}

// rejectStraySend aborts when coins are attached to a call (pearl audit
// Y2): this realm handles no funds, holds no banker and exposes no
// withdrawal, so an attached send would strand on the realm address
// forever. Aborting reverts the transfer back to the sender. Fails open
// for realm-routed calls, whose attached send lands on the intermediary
// realm, never here.
func rejectStraySend(cur realm) {
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("this realm does not accept coins")
	}
}

// ---------- quota index ----------

func quotaAdd(owner address) {
	ownerServices[owner] = ownerServices[owner] + 1
}

func quotaDrop(owner address) {
	n := ownerServices[owner] - 1
	if n <= 0 {
		delete(ownerServices, owner)
		return
	}
	ownerServices[owner] = n
}

func assertQuota(owner address) {
	if ownerServices[owner] >= MaxServicesPerOwner {
		panic("address already holds the maximum of " +
			strconv.Itoa(MaxServicesPerOwner) + " services")
	}
}

// ---------- validation helpers ----------

func isValidName(name string) bool {
	if name == "" || len(name) > MaxNameLen {
		return false
	}
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	return true
}

func validatePkgPath(pkgPath string) {
	if pkgPath == "" {
		panic("pkgpath must not be empty")
	}
	if len(pkgPath) > MaxPkgPathLen {
		panic("pkgpath exceeds " + strconv.Itoa(MaxPkgPathLen) + " chars")
	}
	if !strings.HasPrefix(pkgPath, pkgPathPrefix) {
		panic("pkgpath must start with " + pkgPathPrefix + " and name a package")
	}
	// structural, per-element validation (re-audit: the old charset check
	// accepted "..", "//", trailing slashes, hyphens, and non-r/p roots —
	// all lookalike-squat or allowlist-bypass material)
	elems := strings.Split(pkgPath[len(pkgPathPrefix):], "/")
	if len(elems) < 2 || (elems[0] != "r" && elems[0] != "p") {
		panic("pkgpath must be gno.land/r/... or gno.land/p/...")
	}
	for _, e := range elems[1:] {
		if e == "" {
			panic("pkgpath contains an empty element")
		}
		if !(e[0] >= 'a' && e[0] <= 'z') {
			panic("invalid pkgpath element: " + e)
		}
		for _, c := range e {
			if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
				panic("invalid pkgpath element: " + e)
			}
		}
	}
}

func validateFields(description, serviceType, metadata string) {
	if description == "" {
		panic("description must not be empty")
	}
	if len(description) > MaxDescriptionLen {
		panic("description exceeds " + strconv.Itoa(MaxDescriptionLen) + " chars")
	}
	if serviceType == "" {
		panic("service type must not be empty")
	}
	if len(serviceType) > MaxTypeLen || !isValidName(serviceType) {
		panic("service type must be lowercase alphanumeric with underscores, max " +
			strconv.Itoa(MaxTypeLen) + " chars")
	}
	if len(metadata) > MaxMetadataLen {
		panic("metadata exceeds " + strconv.Itoa(MaxMetadataLen) + " chars")
	}
}

// truncate shortens s to at most n runes without splitting a multibyte
// character. Applied to RAW text, never to escaped output — truncating
// after escaping could sever a `\x` pair and leave a dangling backslash.
func truncate(s string, n int) string {
	if n < 4 {
		panic("truncate: budget too small")
	}
	runes := []rune(s)
	if len(runes) <= n {
		return s
	}
	return string(runes[:n-3]) + "..."
}

func mustGet(name string) *Service {
	svc, ok := services[name]
	if !ok {
		panic("service not found: " + name)
	}
	return svc
}

// ---------- write operations ----------

// RegisterService adds a new service to the registry. The caller becomes
// the owner. Name must be unique, lowercase alphanumeric/underscores.
// pkgPath is the realm the service lives at — the field integrators
// resolve — and must look like a gno.land package path. A name that was
// deregistered stays reserved for its former owner and its original
// registrant for ReservationPeriod.
//
// NOTE: this realm does NOT and cannot verify that pkgPath exists or
// that the caller controls it. See the INTEGRATOR CONTRACT on Resolve.
func RegisterService(cur realm, name, pkgPath, description, serviceType, metadata string) {
	rejectStraySend(cur)
	c := cur.Previous().Address()

	if !isValidName(name) {
		panic("name must be 1-" + strconv.Itoa(MaxNameLen) +
			" chars, lowercase alphanumeric with underscores only")
	}
	validatePkgPath(pkgPath)
	validateFields(description, serviceType, metadata)
	if _, exists := services[name]; exists {
		panic("service already registered: " + name)
	}

	registrant := c
	if res, wasRetired := retired[name]; wasRetired {
		if time.Now().After(res.Expires) {
			// O(1) lazy reclaim: a lapsed tombstone is dropped the moment
			// it is consulted, so the map does not pay to keep entries
			// nobody will ever read again.
			delete(retired, name)
		} else {
			if c != res.Owner && c != res.Registrant {
				panic("name is reserved for its former owner: " + name)
			}
			// round-3 audit: an in-window re-register must PRESERVE the
			// original registrant — otherwise a hostile transferee could
			// deregister and instantly re-register, stamping themselves as
			// registrant and erasing the original project's reclaim right
			if res.Registrant != "" {
				registrant = res.Registrant
			}
		}
	}

	if len(services) >= MaxServices {
		panic("global service limit reached")
	}
	assertQuota(c)

	services[name] = &Service{
		Name:        name,
		Owner:       c,
		Registrant:  registrant,
		PkgPath:     pkgPath,
		Description: description,
		ServiceType: serviceType,
		Metadata:    metadata,
	}
	names = append(names, name)
	quotaAdd(c)
	delete(retired, name)

	chain.Emit("ServiceRegistered",
		"name", name,
		"pkgpath", pkgPath,
		"type", serviceType,
		"owner", c.String(),
		"registrant", registrant.String(),
	)
}

// UpdateService modifies a service's pkgpath, description, type, and
// metadata. Only the registered owner can update. Name cannot change.
//
// An update MAY REPOINT the name at a different package path. That is a
// deliberate capability (services move, and versions supersede), but it
// also means a name an integrator trusts today can point elsewhere
// tomorrow. The ServiceUpdated event carries both the old and the new
// path specifically so a repoint is observable in the transaction log
// rather than something a consumer has to poll for.
func UpdateService(cur realm, name, pkgPath, description, serviceType, metadata string) {
	rejectStraySend(cur)
	svc := mustGet(name)
	if cur.Previous().Address() != svc.Owner {
		panic("only the owner can update this service")
	}
	validatePkgPath(pkgPath)
	validateFields(description, serviceType, metadata)

	oldPath := svc.PkgPath
	svc.PkgPath = pkgPath
	svc.Description = description
	svc.ServiceType = serviceType
	svc.Metadata = metadata

	chain.Emit("ServiceUpdated",
		"name", name,
		"oldpkgpath", oldPath,
		"pkgpath", pkgPath,
		"type", serviceType,
		"owner", svc.Owner.String(),
	)
}

// TransferOwnership NOMINATES a new owner for a service entry; the
// nominee must call AcceptOwnership to take control (pearl audit Y4).
//
// The one-step form this replaces was a permanent-brick hazard:
// address.IsValid() only checks bech32 form, so a well-formed but
// unowned destination passed the check and committed immediately, after
// which the entry could never again be updated, transferred or
// deregistered — and because it could never be deregistered it could
// never enter the reservation window either, so the NAME became a
// permanent hole in a shared global namespace.
//
// Nomination changes nothing: the sitting owner keeps full control
// until the nominee consents. Passing "" clears a pending nomination.
func TransferOwnership(cur realm, name string, newOwner address) {
	rejectStraySend(cur)
	svc := mustGet(name)
	c := cur.Previous().Address()
	if c != svc.Owner {
		panic("only the owner can transfer ownership")
	}
	if newOwner == "" {
		delete(pendingOwners, name)
		chain.Emit("OwnershipTransferCancelled", "name", name, "owner", c.String())
		return
	}
	if !newOwner.IsValid() {
		panic("invalid new owner address: " + string(newOwner))
	}
	if newOwner == svc.Owner {
		panic("new owner is already the owner")
	}
	pendingOwners[name] = newOwner

	chain.Emit("OwnershipTransferProposed",
		"name", name,
		"owner", c.String(),
		"pending", newOwner.String(),
	)
}

// AcceptOwnership completes a nominated handoff. Only the nominee can
// accept, and the nominee's own quota is checked HERE — at consent —
// so a nomination can never push an account past MaxServicesPerOwner
// without that account agreeing to it.
func AcceptOwnership(cur realm, name string) {
	rejectStraySend(cur)
	svc := mustGet(name)
	c := cur.Previous().Address()

	pending, ok := pendingOwners[name]
	if !ok {
		panic("no pending ownership transfer for: " + name)
	}
	if c != pending {
		panic("only the nominated owner can accept")
	}
	assertQuota(c)

	prev := svc.Owner
	svc.Owner = c
	quotaDrop(prev)
	quotaAdd(c)
	delete(pendingOwners, name)

	chain.Emit("OwnershipTransferred",
		"name", name,
		"from", prev.String(),
		"to", c.String(),
	)
}

// CancelOwnershipTransfer withdraws a pending nomination. Owner-only.
func CancelOwnershipTransfer(cur realm, name string) {
	rejectStraySend(cur)
	svc := mustGet(name)
	c := cur.Previous().Address()
	if c != svc.Owner {
		panic("only the owner can cancel a transfer")
	}
	if _, ok := pendingOwners[name]; !ok {
		panic("no pending ownership transfer for: " + name)
	}
	delete(pendingOwners, name)

	chain.Emit("OwnershipTransferCancelled", "name", name, "owner", c.String())
}

// Deregister removes a service from the registry. Only the owner can
// deregister. The name stays reserved for the former owner and the
// original registrant for ReservationPeriod — it cannot be
// re-registered by anyone else in that window, so integrators who still
// resolve it can never be silently redirected by a squatter.
func Deregister(cur realm, name string) {
	rejectStraySend(cur)
	svc := mustGet(name)
	c := cur.Previous().Address()
	if c != svc.Owner {
		panic("only the owner can deregister")
	}
	retired[name] = &Reservation{
		Owner:      svc.Owner,
		Registrant: svc.Registrant,
		Expires:    time.Now().Add(time.Duration(ReservationPeriod) * time.Second),
	}
	delete(services, name)
	quotaDrop(svc.Owner)
	// a nomination must not outlive the entry it was made against
	delete(pendingOwners, name)

	// Remove from ordered list
	for i, n := range names {
		if n == name {
			names = append(names[:i], names[i+1:]...)
			break
		}
	}

	chain.Emit("ServiceDeregistered",
		"name", name,
		"owner", svc.Owner.String(),
		"registrant", svc.Registrant.String(),
	)
}

// ---------- read-only queries ----------

// Resolve returns the pkgpath a service name points to — the primary
// integration query. Panics on unknown names so a consumer can never
// silently integrate against a missing entry.
//
// INTEGRATOR CONTRACT — read this before trusting a resolution:
//
//  1. A resolution is an ATTESTATION, NOT A PROOF. This realm records
//     that some address claimed a name for some package path. It does
//     NOT verify that the path exists, that it is deployed, or that the
//     registrant controls it. Contrast r/demo/defi/grc20reg, which
//     proves control by requiring the registered token object to
//     originate from the calling realm; no equivalent proof exists for
//     a bare path string, and requiring one would mean only realms —
//     never their operators — could ever register a name, which is not
//     this registry's model.
//
//  2. A NAME IS NOT AN AUTHORIZATION. Never grant a privilege, route a
//     payment, or admit a caller because Resolve returned its path.
//     Resolution answers "where does this name point", never "may this
//     caller act". Derive authority from your own crossing entrypoint's
//     cur.Previous(), or from an explicit access-control realm.
//
//  3. THE TARGET CAN CHANGE. The owner may repoint a name at any time
//     via UpdateService, and ownership itself is transferable. Treat a
//     resolution as valid only for the transaction that read it; cache
//     it and you inherit whatever the name points at later. The
//     ServiceUpdated and OwnershipTransferred events exist so movement
//     is detectable.
func Resolve(name string) string {
	return mustGet(name).PkgPath
}

// TryResolve is the non-panicking variant for consumers that need to
// degrade gracefully when a name disappears (re-audit: a panicking-only
// read path bricks any consumer realm that calls it inline). The
// INTEGRATOR CONTRACT documented on Resolve applies here identically.
func TryResolve(name string) (string, bool) {
	svc, ok := services[name]
	if !ok {
		return "", false
	}
	return svc.PkgPath, true
}

// GetOwner returns the owner address of a service.
func GetOwner(name string) address {
	return mustGet(name).Owner
}

// GetPendingOwner returns the nominated-but-not-yet-accepted owner of a
// service, or "none" when no handoff is open.
func GetPendingOwner(name string) string {
	mustGet(name)
	if p, ok := pendingOwners[name]; ok {
		return p.String()
	}
	return "none"
}

// ServiceCount returns how many services are registered and the global
// cap, so a caller can check headroom without pulling the whole list.
func ServiceCount() (count, limit int) {
	return len(services), MaxServices
}

// OwnerServiceCount returns how many services an address currently holds
// and the per-owner cap.
func OwnerServiceCount(owner address) (count, limit int) {
	return ownerServices[owner], MaxServicesPerOwner
}

// GetService returns a formatted summary of a registered service. Free
// text is escaped for a single-line markdown slot.
func GetService(name string) string {
	svc := mustGet(name)

	var b strings.Builder
	b.WriteString("Name: " + svc.Name + "\n")
	b.WriteString("Owner: " + string(svc.Owner) + "\n")
	b.WriteString("PkgPath: " + svc.PkgPath + "\n")
	b.WriteString("Type: " + svc.ServiceType + "\n")
	b.WriteString("Description: " + sanitize.InlineText(svc.Description) + "\n")
	if svc.Metadata != "" {
		b.WriteString("Metadata: " + sanitize.InlineText(svc.Metadata) + "\n")
	}
	return b.String()
}

// ListServices returns all registered service names as a comma-separated
// string in registration order.
//
// COST NOTE: this is O(MaxServices) and is deliberately NOT truncated —
// an integrator enumerating the registry needs the complete set, and the
// caller pays for its own read. Render, whose cost lands on third-party
// viewers instead, IS bounded.
func ListServices() string {
	if len(names) == 0 {
		return "none"
	}
	return strings.Join(names, ", ")
}

// ListByType returns all service names matching a given type. Same cost
// note as ListServices.
func ListByType(serviceType string) string {
	var result []string
	for _, name := range names {
		svc := services[name]
		if svc != nil && svc.ServiceType == serviceType {
			result = append(result, name)
		}
	}
	if len(result) == 0 {
		return "none"
	}
	return strings.Join(result, ", ")
}

// ---------- render ----------

// Render returns a markdown overview, bounded to MaxRenderServices rows
// (pearl audit Y3). Never panics. All free text goes through the
// ecosystem sanitizer rather than a bespoke escaper: the hand-rolled
// replacement of backticks and pipes it replaces left `[`, `]`, `(`,
// `)` and `!` live, so any registrant could inject a working markdown
// link or image into a table cell and phish every viewer of this page.
func Render(path string) string {
	total := len(services)
	if total == 0 {
		return "# Service Registry\n\nNo services registered.\n"
	}

	var b strings.Builder
	b.WriteString("# Service Registry\n\n")
	b.WriteString("**Total services:** " + strconv.Itoa(total) + "\n\n")

	b.WriteString("| Name | Type | PkgPath | Owner | Description |\n")
	b.WriteString("|------|------|---------|-------|-------------|\n")

	shown := 0
	for _, name := range names {
		if shown >= MaxRenderServices {
			break
		}
		svc := services[name]
		if svc == nil {
			continue
		}
		desc := sanitize.TableCell(truncate(svc.Description, renderDescLen))
		b.WriteString("| " + svc.Name + " | " + svc.ServiceType + " | `" +
			svc.PkgPath + "` | `" + string(svc.Owner) + "` | " + desc + " |\n")
		shown++
	}

	if shown < total {
		b.WriteString("\n_Showing " + strconv.Itoa(shown) + " of " +
			strconv.Itoa(total) + " services. Use ListServices, ListByType " +
			"or GetService for complete data._\n")
	}

	b.WriteString("\n")
	return b.String()
}
